  } else if (fireReady) {
    if (isBoss) fireBossSpread(state, mob, dmgScale, deps.emit);
    else fireMobArrow(state, mob, SKELETON_ARROW_DAMAGE * dmgScale, SKELETON_ARROW_SPEED, deps.emit);
