handleEvent(event: GameEvent, state: GameState): void {
  switch (event.type) {
    case "blockBroken":
      this.particles.emitBurst({
        x: event.x + 0.5,
        y: event.y + 0.5,
        z: event.z + 0.5,
        count: 10,
        color: BLOCK_COLORS[event.blockId] ?? [0.6, 0.6, 0.6],
        speed: 3.2,
        spread: 1.0,
        gravity: 14,
        drag: 1.6,
        life: [0.35, 0.7],
        size: 0.16,
        colorJitter: 0.08
      });
      break;
    case "blockPlaced":
      this.particles.emitBurst({
        x: event.x + 0.5,
        y: event.y + 0.5,
        z: event.z + 0.5,
        count: 6,
        color: BLOCK_COLORS[event.blockId] ?? [0.6, 0.6, 0.6],
        speed: 1.2,
        spread: 0.6,
        gravity: 6,
        drag: 2.2,
        life: [0.25, 0.45],
        size: 0.12,
        upBias: 0.6
      });
      break;
    case "mobDied":
      this.particles.emitBurst({
        x: event.x,
